insert into public.module_version (default_currency, id, module_id, version, status, default_price, default_props) values ('EUR', '00000000-0000-4000-8000-0000000e1061', '00000000-0000-4000-8000-00000000e106', 1, 'published', null, $json${"eyebrow":"Cómo lo vive el invitado","title":"Sin descargar nada, desde su móvil","lede":"Toca cada paso: así pide, sube su foto y sale en la pantalla de {company}.","djName":"DJ Mikel","price":2,"photos":["/demo/enjoy/img/album/album-01.webp","/demo/enjoy/img/album/album-02.webp","/demo/enjoy/img/album/album-03.webp","/demo/enjoy/img/album/album-04.webp","/demo/enjoy/img/album/album-05.webp","/demo/enjoy/img/album/album-06.webp"],"qrImage":"/demo/enjoy/img/qr.webp","autoplay":true}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000000b1001', '00000000-0000-4000-8000-0000000b0101', 1, 'published', null, 'EUR', $json${"title":"Cómo funciona","cards":[{"icon":"calendar","title":"1. Creas la inmersión.","body":"Hora, punto de inmersión y tipo. Los datos del punto ya están cargados: profundidad máxima, tiempo habitual, visibilidad, vida marina."},{"icon":"qr","title":"2. El buceador escanea tu QR.","body":"Elige la inmersión de hoy y la guarda. Su logbook queda relleno sin escribir nada."},{"icon":"users","title":"3. A ti te queda el registro.","body":"Cada buceador que guarda una inmersión entra en tu lista, con todo lo que ha hecho contigo."}],"screens":[{"screen":"create-activity"},{"screen":"qr-activity"},{"screen":"crm-list"}]}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000000b1002', '00000000-0000-4000-8000-0000000b0102', 1, 'published', null, 'EUR', $json${"title":"Tu nombre en cada inmersión","highlight":"Tu nombre","lede":"El buceador puede exportar una tarjeta de su inmersión para compartirla. Hay tres: la de la inmersión, la de récord personal y la de hito.","cards":[{"icon":"check","title":"En todas aparece el nombre de tu centro."}],"screens":[{"screen":"share-card"}]}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000000b1003', '00000000-0000-4000-8000-0000000b0103', 1, 'published', null, 'EUR', $json${"eyebrow":"Desde el ordenador del centro","title":"Todo tu centro, en una pantalla","highlight":"en una pantalla","lede":"Lo que hace el día a día: tus salidas, quién viene a cada una y tu lista de buceadores.","views":[{"view":"today","label":"Hoy","says":"Las salidas del día y cuántos buceadores tienes ya en tu CRM."},{"view":"activity","label":"Quién viene","says":"En cada salida ves quién escaneó el QR y a quién añadiste a mano."},{"view":"crm","label":"CRM","says":"Cada buceador, con su historial en tu centro y tus notas internas."},{"view":"centre","label":"Tu centro","says":"Tu QR, tu perfil público y cómo te ven los buceadores."}]}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1001', '00000000-0000-4000-8000-0000005c0101', 1, 'published', null, 'EUR', $json${"eyebrow":"Propuesta para {company}","title":"Lo que tu página afirma, con la evidencia a la vista","subtitle":"Comprobamos qué respaldo tiene lo que publicas, si el mensaje se ajusta al marco aplicable y si la redacción transmite lo que la evidencia permite afirmar. Si el informe es favorable, el sello lo dice junto a esas afirmaciones.","rotatingWords":[],"ctas":[],"stats":[]}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1002', '00000000-0000-4000-8000-0000005c0102', 1, 'published', null, 'EUR', $json${"eyebrow":"Hoy","title":"Tu página afirma cosas que nadie de fuera ha comprobado","beforeLabel":"Hoy","afterLabel":"Con SciScreen","cards":[{"problem":"Tu página dice que el producto ayuda a algo y nadie fuera de tu equipo ha comprobado si los estudios lo sostienen tal como está escrito.","solution":"Revisamos cada afirmación: qué estudios hay, cuánta confianza merecen, qué permite la normativa y qué entiende el lector."},{"problem":"Quien te compra no puede saber qué afirmaciones están respaldadas.","solution":"Si el informe es favorable, el sello abre en sciscreen.com qué se revisó, cuándo y con qué alcance."},{"problem":"Una afirmación que no se sostiene es un riesgo con la normativa de publicidad.","solution":"El informe te dice qué puede mantenerse, qué conviene reformular y qué necesita más documentación, antes de publicar."}],"note":"El sello no certifica el producto ni toda la web, ni es una autorización administrativa o un aval sanitario: dice qué se revisó, cuándo y con qué alcance."}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1003', '00000000-0000-4000-8000-0000005c0103', 1, 'published', null, 'EUR', $json${"eyebrow":"Tu página, con el sello","title":"Así se vería el sello en {company}","lede":"Tu página tal cual, con el sello junto a sus afirmaciones. Quien la visita lo pulsa y abre en sciscreen.com qué se revisó, contra qué estudios y hasta cuándo.","seals":[{"size":"compacto","ground":"claro","x":4,"y":70}],"press":0,"simulation":"Simulación","hint":"Pulsa el sello","replay":"Volver a verlo","back":"Volver a su web","captions":{"start":"Así se vería {company} con el sello de SciScreen.","seal":"El sello va junto a las afirmaciones y dice cuándo se revisaron.","click":"Quien duda, lo pulsa…","page":"…y abre en sciscreen.com qué se revisó, con qué estudios y hasta cuándo. Lo dice un tercero, no la marca."},"page":{"path":"sciscreen.com/es/sello/","status":"Vigente","reviewed":"Revisado el {date}","validUntil":"{nextYear}","claims":[{"text":"La vitamina C contribuye al funcionamiento normal del sistema inmunitario.","evidence":"Declaración autorizada · Reglamento (UE) 432/2012","sources":[{"title":"Reglamento (UE) n.º 432/2012, declaraciones de propiedades saludables permitidas","ref":"Diario Oficial de la Unión Europea · 2012"}]},{"text":"El zinc contribuye a la protección de las células frente al daño oxidativo.","evidence":"Declaración autorizada · Reglamento (UE) 432/2012","sources":[{"title":"Reglamento (UE) n.º 432/2012, declaraciones de propiedades saludables permitidas","ref":"Diario Oficial de la Unión Europea · 2012"}]}]},"fallback":{"address":"tumarca.com","claims":["La vitamina C contribuye al funcionamiento normal del sistema inmunitario.","El zinc contribuye a la protección de las células frente al daño oxidativo."]},"note":"Simulación: {company} aún no está verificada y estas afirmaciones son de ejemplo. El sello indica que las afirmaciones de esa página, en la versión revisada, tienen un informe favorable; no certifica el producto ni toda la web."}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1004', '00000000-0000-4000-8000-0000005c0104', 1, 'published', null, 'EUR', $json${"eyebrow":"El sello","title":"El sello, junto a lo que afirma","lede":"Quien lee tu página ve qué se revisó y cuándo. El sello abre su página en sciscreen.com, con la dirección verificada tal cual.","seal":{"alt":"Sello de SciScreen: Verificado a día de hoy","size":"tarjeta","ground":"claro"},"ground":"paper","page":{"label":"Simulación","address":"tumarca.com/producto","claims":["La vitamina C contribuye al funcionamiento normal del sistema inmunitario.","Con 20 g de proteína por ración."]},"rules":["Solo con un informe favorable y cumpliendo las condiciones de uso","Limitado a los contenidos y a la versión revisados: si la página cambia, se vuelve a revisar","Junto a las afirmaciones (compacto), en una sección de ciencia (placa) o en la portada (tarjeta); y en el pie de cada página verificada","Nunca en páginas sin revisar, envases ni publicidad","Abre su página en sciscreen.com: qué se revisó, cuándo y con qué alcance"],"states":[{"name":"Vigente","body":"El informe es favorable para la versión revisada y la cuota está al día. Se lee «Verificado a día» y la fecha."},{"name":"Pendiente de renovación","body":"Si no se renueva, el sello espera 30 días. Al renovar, vuelve el mismo."},{"name":"Retirado","body":"Pasados esos 30 días no se pinta nada. Al renovar, vuelve el mismo sello."},{"name":"Revocado","body":"Si una revisión concluye que la conclusión ya no es válida: cambió el contenido, la fórmula, la evidencia o la norma. Nunca por un pago."}],"note":"El sello no certifica el producto ni toda la web, ni es una autorización administrativa o un aval sanitario: dice qué se revisó, cuándo y con qué alcance."}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1005', '00000000-0000-4000-8000-0000005c0105', 1, 'published', null, 'EUR', $json${"eyebrow":"Hoy","title":"Lo que se dice de tu producto lo cuentan webs que no son tuyas","beforeLabel":"Hoy","afterLabel":"Con SciScreen","cards":[{"problem":"Tu producto se vende en farmacias, herbolarios y tiendas online, y cada una lo cuenta en su web, a su manera.","solution":"Revisamos las afirmaciones de esas páginas: su evidencia, su calidad, el marco regulatorio y lo que entiende quien las lee."},{"problem":"Quien compra en esas tiendas no puede saber qué afirmaciones sobre tu producto están respaldadas.","solution":"Si el informe es favorable, el sello junto a esas afirmaciones abre la prueba en sciscreen.com: lo dice un tercero, no la tienda ni la marca."},{"problem":"Un estudio sobre un ingrediente no demuestra el efecto de tu fórmula comercial, y la web puede decir lo contrario.","solution":"El informe separa lo que permite afirmar la ciencia de lo que puede comunicarse, y te dice qué reformular o documentar."}],"note":"El sello no certifica el producto ni toda la web, ni es una autorización administrativa o un aval sanitario: dice qué se revisó, cuándo y con qué alcance."}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1006', '00000000-0000-4000-8000-0000005c0106', 1, 'published', null, 'EUR', $json${"eyebrow":"Tu producto, en sus tiendas","title":"El sello junto a tu producto, en una tienda que lo vende","lede":"Cada farmacia, herbolario o tienda online enseña tu producto a su manera. El sello se ve en cualquiera y abre en sciscreen.com lo que se revisó.","seals":[{"size":"placa","ground":"claro","x":44,"y":44,"scale":1.5}],"press":0,"simulation":"Simulación","hint":"Pulsa el sello","replay":"Volver a verlo","back":"Volver a la tienda","captions":{"start":"Así se vería tu producto en una tienda que lo vende, con el sello de SciScreen.","seal":"Cada tienda tiene su web; el sello destaca en todas, junto a tu producto.","click":"Quien duda, lo pulsa…","page":"…y ve en sciscreen.com qué se revisó y con qué estudios: lo dice un tercero."},"page":{"path":"sciscreen.com/es/sello/","status":"Vigente","reviewed":"Revisado el {date}","validUntil":"{nextYear}","claims":[{"text":"El magnesio contribuye a disminuir el cansancio y la fatiga.","evidence":"Declaración autorizada · Reglamento (UE) 432/2012","sources":[{"title":"Reglamento (UE) n.º 432/2012, declaraciones de propiedades saludables permitidas","ref":"Diario Oficial de la Unión Europea · 2012"}]},{"text":"La vitamina B6 contribuye al funcionamiento normal del sistema nervioso.","evidence":"Declaración autorizada · Reglamento (UE) 432/2012","sources":[{"title":"Reglamento (UE) n.º 432/2012, declaraciones de propiedades saludables permitidas","ref":"Diario Oficial de la Unión Europea · 2012"}]}]},"fallback":{"address":"tienda.com/tu-producto","claims":["El magnesio contribuye a disminuir el cansancio y la fatiga.","La vitamina B6 contribuye al funcionamiento normal del sistema nervioso."]},"note":"Simulación: {company} aún no está verificada, la tienda es de ejemplo y estas afirmaciones también. El sello indica que las afirmaciones de esa página, en la versión revisada, tienen un informe favorable; no certifica el producto ni toda la web."}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1007', '00000000-0000-4000-8000-0000005c0107', 1, 'published', null, 'EUR', $json${"eyebrow":"Metodología propia EQRC","title":"Cuatro preguntas para cada afirmación","autoAdvanceMs":5500,"tabs":[{"label":"Evidencia","title":"¿Qué estudios responden a la pregunta?","body":"Separamos cada afirmación de la página y precisamos qué dice, de qué principio activo o producto, para quién y en qué condiciones. Después buscamos qué se estudió de verdad, con los resultados favorables y los que los contradicen.","bullets":["Un estudio citado no siempre respalda todo lo que sugiere la página"],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/eqrc-1.svg","alt":"Las cuatro preguntas del método EQRC, con Evidencia resaltada"}},{"label":"Calidad","title":"¿Cuánta confianza merecen los resultados?","body":"Valoramos el riesgo de sesgo, la precisión y la concordancia entre estudios, y si se aplican al principio activo o producto, a la dosis y a la población de la que habla la página. Comprobamos si alguna fuente se ha corregido o retractado.","bullets":[],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/eqrc-2.svg","alt":"Las cuatro preguntas del método EQRC, con Calidad resaltada"}},{"label":"Regulación","title":"¿Puede comunicarse ese mensaje en ese contexto?","body":"Desde el inicio identificamos qué normas se aplican al producto, al mercado y al tipo de comunicación. Si hay una declaración autorizada, comprobamos en el Registro de la UE que se mantenga su significado y que se cumplan sus condiciones de uso.","bullets":["Un estudio favorable no sustituye una autorización exigible"],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/eqrc-3.svg","alt":"Las cuatro preguntas del método EQRC, con Regulación resaltada"}},{"label":"Comunicación","title":"¿Qué entiende el lector?","body":"Revisamos el titular, el texto y las imágenes: si convierten una asociación en una causa, atribuyen al producto lo estudiado en un ingrediente u omiten una condición que cambia el significado.","bullets":["Las cuatro preguntas no se compensan entre sí"],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/eqrc-4.svg","alt":"Las cuatro preguntas del método EQRC, con Comunicación resaltada"}}]}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1008', '00000000-0000-4000-8000-0000005c0108', 1, 'published', null, 'EUR', $json${"eyebrow":"Inversión","title":"Propuesta para {company}","subtitle":"Una cuota anual: la revisión, el informe y hasta tres revisiones más en el año para comprobar que la conclusión sigue siendo válida.","features":["Revisión de cada afirmación: evidencia, calidad, regulación y comunicación","Informe documentado: fuentes, conclusiones y recomendaciones de cambio","Hasta tres revisiones más durante el año","Si el informe es favorable, el sello y su página en sciscreen.com"],"noPriceLabel":"Según las páginas que verifiquemos","taxNote":"IVA no incluido","smallPrint":"La cuota remunera la revisión y el informe; no garantiza el sello ni un resultado favorable. Si no se renueva, el sello queda pendiente 30 días y después se retira."}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c1009', '00000000-0000-4000-8000-0000005c0109', 1, 'published', null, 'EUR', $json${"eyebrow":"La pirámide de la evidencia","title":"Qué conclusión permite cada estudio","autoAdvanceMs":5000,"tabs":[{"label":"1. Exploratoria","title":"Indicios, no beneficios","body":"Los estudios de laboratorio, en animales o los casos clínicos pueden sugerir un mecanismo o una hipótesis. Por sí solos no demuestran un beneficio en personas.","bullets":[],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/piramide-1.svg","alt":"Pirámide de la evidencia con el escalón 1, Exploratoria, resaltado"}},{"label":"2. Asociación","title":"Una relación, no una causa","body":"Los estudios transversales o de casos y controles detectan una relación entre dos factores. No demuestran que uno cause el otro.","bullets":[],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/piramide-2.svg","alt":"Pirámide de la evidencia con el escalón 2, Asociación, resaltado"}},{"label":"3. Seguimiento","title":"Qué pasa con el tiempo","body":"Las cohortes observan si la exposición precede al resultado a lo largo del tiempo. Aun así, pueden influir otros factores.","bullets":[],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/piramide-3.svg","alt":"Pirámide de la evidencia con el escalón 3, Seguimiento, resaltado"}},{"label":"4. Intervención","title":"Si la intervención produjo el efecto","body":"Los ensayos, sobre todo aleatorizados y con comparador, ayudan a evaluar si la intervención produjo el efecto en las condiciones estudiadas.","bullets":[],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/piramide-4.svg","alt":"Pirámide de la evidencia con el escalón 4, Intervención, resaltado"}},{"label":"5. Síntesis","title":"Revisiones y metaanálisis","body":"Las revisiones sistemáticas reúnen y evalúan los estudios; un metaanálisis combina sus resultados. Estar en la cúspide no garantiza una conclusión sólida: no corrige los sesgos de lo que incluye.","bullets":["Un buen estudio puede no responder a la afirmación: otra dosis u otro efecto"],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/piramide-5.svg","alt":"Pirámide de la evidencia con el escalón 5, Síntesis, resaltado"}}]}$json$::jsonb);
insert into public.module_version (id, module_id, version, status, default_price, default_currency, default_props) values ('00000000-0000-4000-8000-0000005c100a', '00000000-0000-4000-8000-0000005c010a', 1, 'published', null, 'EUR', $json${"eyebrow":"Qué recibe vuestro equipo","title":"Un informe documentado, afirmación por afirmación","autoAdvanceMs":6000,"tabs":[{"label":"El informe","title":"Mantener, reformular o aportar documentación","body":"Con el alcance y la versión revisados, las fuentes, la conclusión de cada afirmación y las recomendaciones de cambio. Si falta un dato, el informe dice cuál y por qué importa. La decisión final pasa por revisión humana.","bullets":[],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/informe-conclusiones.svg","alt":"Informe de revisión con tres afirmaciones: mantener, reformular y aportar documentación"}},{"label":"El resultado","title":"Favorable, condicionado o no favorable","body":"Para la versión evaluada. Si hay una vía de mejora, indicamos qué corregir y qué habría que comprobar en la nueva versión.","bullets":["Un resultado condicionado no autoriza el uso del sello"],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/informe-resultados.svg","alt":"Los tres resultados posibles: favorable, favorable condicionado y no favorable"}},{"label":"Un ejemplo","title":"Un ingrediente no es la fórmula","body":"Una ficha afirma que «nuestro producto ha demostrado este beneficio», pero el estudio citado evalúa un ingrediente, no la fórmula comercial. El informe lo señala, explica qué permite concluir el estudio y qué redacción podría revisarse.","bullets":[],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/informe-ejemplo.svg","alt":"Ejemplo: la ficha atribuye al producto lo que el estudio vio en un ingrediente"}},{"label":"Con vuestro equipo","title":"Una segunda lectura documentada","body":"Si ya tenéis Regulatory, I+D o Calidad, SciScreen no sustituye su trabajo: aporta una segunda lectura de lo que se publica, para comprobar que el mensaje refleja el respaldo que tenéis y volver a revisarlo cuando cambien las circunstancias.","bullets":[],"mock":{"kind":"image","src":"/demo/sciscreen/img/metodo/eqrc-1.svg","alt":"Las cuatro preguntas del método EQRC"}}]}$json$::jsonb);
insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image) values ('00000000-0000-4000-8000-0000005e0001', '00000000-0000-4000-8000-000000000e01', 'bodas', 'Bodas', 'Novios que celebran su boda y las fincas/salas que la acogen.', 'El banquete se convierte en algo que los invitados hacen, no que miran: recuerdos compartidos sin descargar ninguna app.', '- Bodas de 100+ invitados
insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image, proposal) values ('00000000-0000-4000-8000-0000005e0002', '00000000-0000-4000-8000-000000000e01', 'ocio-nocturno', 'Locales de ocio nocturno', 'Discotecas, pubs y salas con programación semanal.', 'Más tiempo en pista, más consumo y clientes que vuelven: el público interactúa con la pantalla y genera contenido para redes.', '- Aforo 300+ y pantallas en sala
insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image, notice) values ('00000000-0000-4000-8000-0000005e0003', '00000000-0000-4000-8000-000000000e01', 'conciertos', 'Conciertos', 'Promotoras y salas de conciertos (giras y fechas sueltas).', 'Interacción del público con el artista y datos de asistentes para la promotora y las marcas.', '- Salas de 500+ personas con pantalla
insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image, notice) values ('00000000-0000-4000-8000-0000005e0004', '00000000-0000-4000-8000-000000000e01', 'festivales', 'Festivales', 'Festivales de música con patrocinadores y zonas comunes.', 'Activaciones de marca medibles y experiencia en zonas comunes y entre conciertos.', '- 5.000+ asistentes
insert into public.segment (id, tenant_id, key, name, description, value_prop, icp, disqualifiers, buying_process, deal_size, sales_cycle, position, status, icon, image, proposal) values ('00000000-0000-4000-8000-0000005c5e01', '00000000-0000-4000-8000-000000005c01', 'salud-natural', 'Complementos y salud natural', 'Marcas de complementos alimenticios, herbolario y salud natural que hacen afirmaciones sobre sus productos: las que venden en su web y los laboratorios con marca propia que venden en farmacias, herbolarios y tiendas online.', 'Lo que se afirma del producto, revisado contra la literatura científica por un tercero, con el sello junto a las afirmaciones y la prueba en sciscreen.com. El sello no certifica el producto ni la marca: certifica que las afirmaciones de esa página se han revisado.', '- Marcas con tienda online o web de producto con afirmaciones de salud
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0001', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'novios', 'Novios', 'decisor', 'Una boda que los invitados recuerden y en la que todos participen.', 'Tiempos muertos en el banquete, mesas que no se mezclan, invitados mayores que no participan.', null, '{"precio","tiempo"}', 'Reunión o videollamada con los DOS. Haz la demo en su propio móvil: que envíen una kiss-cam y la vean en pantalla.', 'Tecnicismos y hablar de "plataforma". Hablar solo con uno de los dos.', 'Si les encanta, lo enseñan a la finca y a sus amigos que se casan (referidos).', 'Si no lo entienden en 2 minutos, lo descartan como "otra cosa más que pagar".', 1024);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0002', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'coordinadora-finca', 'Coordinador/a de la finca', 'guardian', 'Que el día salga perfecto y sin problemas técnicos.', 'Proveedores externos que llegan tarde, ocupan espacio o fallan.', null, '{"desconfianza","ya_tengo_proveedor"}', 'Preséntate antes del evento, pásale la ficha técnica y ofrece montaje sin trabajo para su equipo.', 'Saltártela hablando solo con los novios: lo vivirá como una imposición.', 'Si confía en ti, te mete en su lista de proveedores recomendados (canal recurrente).', 'Puede decir "aquí no se puede montar" y tumbarlo en un minuto.', 2048);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0003', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'gerente-finca', 'Gerente de la finca/sala', 'decisor', 'Llenar fechas y diferenciarse de las fincas de alrededor.', 'Competencia en precio, bodas que se pierden contra otra finca.', 'Bodas al año, ticket medio por boda.', '{"precio","no_lo_necesito"}', 'Con números: "si ganas 3 bodas más al año por diferenciación, Enjoy se paga varias veces". Propón una boda piloto.', 'Venderle a los novios saltándote a la finca.', 'Lo incluye en su pack de bodas: volumen recurrente.', 'Prohíbe proveedores externos o exige exclusividad con los suyos.', 3072);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0004', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'dj-boda', 'DJ de la boda', 'influenciador', 'Que la pista se llene y quedar como el que lo hizo posible.', 'Que otro proveedor le quite protagonismo o le complique el directo.', null, '{"ya_tengo_proveedor","desconfianza"}', 'Plantéalo como SU herramienta: él lanza los retos desde el micro. Llámale antes del evento.', 'Venderlo como "algo que anima la boda" (eso es su trabajo).', 'Lo anima en directo y dispara la participación.', 'No cede pantalla ni micro, o lo ignora durante la fiesta.', 4096);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0005', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0001', 'wedding-planner', 'Wedding planner', 'campeon', 'Sorprender a sus novios y diferenciar su servicio.', 'Repetir las mismas ideas en todas las bodas.', null, '{"comparar"}', 'Propón un acuerdo de recomendación y una demo para su cartera de novios.', 'Tratarle como un intermediario más.', 'Prescribe a varias parejas por temporada.', 'Si una boda sale mal, no te vuelve a recomendar.', 5120);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0006', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0002', 'propietario-local', 'Propietario/gerente del local', 'decisor', 'Más consumo por cliente y que vuelvan cada semana.', 'Noches flojas entre semana, competencia de otros locales.', 'Caja por noche, ocupación, repetición.', '{"precio","no_lo_necesito"}', 'Visita por la tarde (nunca en plena noche) con datos de otro local y una demo en su pantalla.', 'Llamarle un sábado por la noche; hablar de "experiencia" sin hablar de caja.', 'Decide rápido si ve el retorno.', 'El precio mensual si no ve el retorno en caja.', 6144);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0007', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0002', 'rrpp-marketing', 'RRPP / marketing del local', 'campeon', 'Contenido para redes y base de datos de clientes.', 'No saber quién viene ni cómo volver a llamarlos.', 'Seguidores, asistentes a eventos, base de datos.', '{"no_decido_yo"}', 'Enséñale el contenido que genera una noche y la captación de datos de asistentes.', 'Darle todo el mérito al dueño delante de él.', 'Lo defiende internamente y lo usa cada semana.', 'Si no lo ve útil para redes, no lo empuja.', 7168);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0008', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0002', 'dj-residente', 'DJ residente', 'guardian', 'Control total de la pista y de la sesión.', 'Interrupciones y cosas que cortan el ritmo.', null, '{"desconfianza"}', 'Habla con él ANTES de la demo con el dueño; que decida en qué momentos de la sesión se lanza cada reto.', 'Imponérselo a través del dueño.', 'Lo integra en la sesión y lo convierte en parte del show.', 'Lo ignora o lo sabotea: sin él no hay participación.', 8192);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0009', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0002', 'marca-bebidas', 'Marca de bebidas patrocinadora', 'pagador', 'Visibilidad y activaciones medibles en el local.', 'Activaciones caras sin datos de resultado.', 'Impactos, participación, leads.', '{"comparar","precio"}', 'Propón una activación cofinanciada con el local: retos patrocinados con su marca en pantalla.', 'Pedirle dinero sin enseñar métricas.', 'Paga parte (o todo) el coste para el local.', 'Si no hay datos, no repite.', 9216);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0010', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0003', 'promotor', 'Promotor/a', 'decisor', 'Una experiencia diferencial y más ingresos por patrocinio.', 'Márgenes ajustados y no conocer a su público.', 'Entradas vendidas, ingresos por patrocinio.', '{"precio","tiempo"}', 'Ofrece un piloto en una fecha con una marca que lo cofinancie.', 'Pedirle compromiso para toda la gira de entrada.', 'Lo extiende a la gira y a otros artistas.', 'Si no hay patrocinio, el precio lo frena.', 10240);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0011', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0003', 'manager-artista', 'Manager del artista', 'guardian', 'Proteger la imagen del artista y el show.', 'Cosas que distraen o mensajes inapropiados en pantalla.', null, '{"desconfianza"}', 'Enséñale la moderación previa y el control total de lo que sale en pantalla.', 'Que se entere por el promotor el día del concierto.', 'Si al artista le gusta, lo pide en otras fechas.', 'Veto directo: "esto no sale en nuestro show".', 11264);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0012', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0003', 'marca-patrocinadora', 'Marca patrocinadora', 'pagador', 'Visibilidad entre el público objetivo con métricas.', 'Logos en una lona que nadie mira.', 'Impactos, participación, leads.', '{"comparar"}', 'Propuesta de activación con KPIs: participaciones, datos captados, contenido.', 'Venderle "visibilidad" sin números.', 'Paga la activación.', 'Sin datos, no renueva.', 12288);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0013', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0004', 'director-festival', 'Dirección del festival', 'decisor', 'Diferenciar el festival y aumentar ingresos.', 'Presupuesto cerrado meses antes.', 'Asistentes, ingresos, prensa.', '{"tiempo","precio"}', 'Llega al menos 6 meses antes de la edición con un caso y una propuesta para patrocinios.', 'Llegar con la temporada empezada.', 'Lo convierte en seña de identidad del festival.', 'Si llega tarde, no hay presupuesto.', 13312);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0014', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0004', 'responsable-patrocinios', 'Responsable de patrocinios', 'campeon', 'Tener activaciones nuevas y medibles que vender a las marcas.', 'Marcas que no renuevan por falta de resultados.', 'Ingresos por patrocinio, renovaciones.', '{"no_decido_yo"}', 'Dale un dossier pensado para que él se lo venda a sus marcas (con métricas de ejemplo).', 'Competir con sus propios patrocinios.', 'Lo vende a varias marcas: multiplica el acuerdo.', 'Si no ve cómo venderlo, no lo mueve.', 14336);
insert into public.persona (id, tenant_id, segment_id, key, name, role, goals, pains, kpis, objections, how_to_approach, avoid, can_help, can_block, position) values ('00000000-0000-4000-8000-0000009e0015', '00000000-0000-4000-8000-000000000e01', '00000000-0000-4000-8000-0000005e0004', 'produccion-tecnica', 'Producción técnica', 'guardian', 'Que nada técnico falle en directo.', 'Conectividad, pantallas compartidas, riesgos.', null, '{"desconfianza"}', 'Ficha técnica, requisitos de red y una prueba previa en el recinto.', 'Prometer cosas técnicas sin haber visto el recinto.', 'Facilita el montaje y la red.', 'Veto técnico: "no hay red", "la pantalla no es vuestra".', 15360);
