insert into public.situation_facet (id, tenant_id, key, label, question, icon, scope, multi, weight, position, options, status) values ('00000000-0000-4000-8000-0000000f0001', '00000000-0000-4000-8000-000000000e01', 'personalidad', 'Tipo de personalidad', '¿Cómo es la persona con la que hablas?', 'smile', 'contact', false, 2, 1024, $json$[{"key":"analitico","label":"Analítico","icon":"chart-column","hint":"Quiere datos, pruebas y detalle. Dale tiempo y números."},{"key":"directo","label":"Directo","icon":"zap","hint":"Va al resultado. Sé breve y ve al grano."},{"key":"expresivo","label":"Expresivo","icon":"sparkles","hint":"Se mueve por la idea y la emoción. Cuéntale la experiencia."},{"key":"afable","label":"Afable","icon":"heart-handshake","hint":"Valora la relación y la confianza. No le presiones."}]$json$::jsonb, 'official');
